def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    count = {}
    for val in a:
        count[val] = count.get(val, 0) + 1

    result = 0
    for k, v in count.items():
        if v > 1:
            result += v * (v - 1) // 2

    # Additional valid pairs: (2^k, 2^l) such that (2^k)^(2^l) = (2^l)^(2^k)
    # This happens when k * 2^l = l * 2^k
    # Known small solutions: (2,4) and (4,2) -> both give 4096
    # So we check for pairs (2,4) and (4,2), i.e., k=2,l=4 or k=4,l=2
    if 2 in count and 4 in count:
        result += count[2] * count[4]

    print(result)

