def can_make_square(grid):
    def count_same_color(square):
        return len(set(square)) == 1

    def get_2x2_squares():
        squares = []
        for i in range(2):
            for j in range(2):
                square = [grid[i][j], grid[i][j+1], grid[i+1][j], grid[i+1][j+1]]
                squares.append(square)
        return squares

    # Check if any 2x2 square already has all same colors
    for square in get_2x2_squares():
        if count_same_color(square):
            return True

    # Try changing each cell one by one
    for i in range(3):
        for j in range(3):
            original = grid[i][j]
            grid[i][j] = 'W' if original == 'B' else 'B'

            for square in get_2x2_squares():
                if count_same_color(square):
                    grid[i][j] = original
                    return True

            grid[i][j] = original

    return False
