def isValid(word: str) -> bool:
    vowels = set('aeiouAEIOU')
    if len(word) < 3:
        return False
    has_vowel = False
    has_consonant = False
    for ch in word:
        if ch.isdigit():
            continue
        elif ch.isalpha():
            if ch in vowels:
                has_vowel = True
            else:
                has_consonant = True
        else:
            return False
    return has_vowel and has_consonant
