def solve():
    import sys
    from itertools import permutations

    def rotate(grid):
        return [list(row) for row in zip(*grid[::-1])]

    def flip(grid):
        return [row[::-1] for row in grid]

    def extract_shape(poly):
        cells = [(i, j) for i in range(4) for j in range(4) if poly[i][j] == '#']
        min_i = min(r for r, c in cells)
        min_j = min(c for r, c in cells)
        return tuple(sorted((r - min_i, c - min_j) for r, c in cells))

    def get_orientations(shape_grid):
        orientations = set()
        g = [list(row) for row in shape_grid]
        for _ in range(4):
            g = rotate(g)
            norm = extract_shape(g)
            orientations.add(norm)
            orientations.add(extract_shape(flip(g)))
        return orientations

    lines = [line.strip() for line in sys.stdin.readlines()]
    polys = []
    for i in range(3):
        grid = lines[i*4:(i+1)*4]
        polys.append(get_orientations(grid))

    board = [[False]*4 for _ in range(4)]

    def can_place(shape, r, c, board):
        for dr, dc in shape:
            nr, nc = r + dr, c + dc
            if nr < 0 or nr >= 4 or nc < 0 or nc >= 4 or board[nr][nc]:
                return False
        return True

    def place(shape, r, c, board, mark):
        for dr, dc in shape:
            board[r+dr][c+dc] = mark

    def backtrack(idx, board):
        if idx == 3:
            return all(board[i][j] for i in range(4) for j in range(4))
        for orient in polys[idx]:
            for r in range(4):
                for c in range(4):
                    if can_place(orient, r, c, board):
                        place(orient, r, c, board, True)
                        if backtrack(idx+1, board):
                            return True
                        place(orient, r, c, board, False)
        return False

    print("Yes" if backtrack(0, board) else "No")

solve()
