import sys
from collections import defaultdict
import heapq

def main():
    data = sys.stdin.read().split()
    if not data:
        print("No")
        return

    n = int(data[0])
    m = int(data[1])

    graph = defaultdict(list)
    edges = []

    index = 2
    for _ in range(m):
        u = int(data[index])
        v = int(data[index+1])
        w = int(data[index+2])
        index += 3
        graph[u].append((v, w))
        edges.append((u, v, w))

    # Floyd-Warshall to compute shortest paths between all pairs
    INF = float('inf')
    dist = [[INF] * (n+1) for _ in range(n+1)]

    for i in range(1, n+1):
        dist[i][i] = 0

    for u, v, w in edges:
        dist[u][v] = min(dist[u][v], w)

    # Floyd-Warshall
    for k in range(1, n+1):
        for i in range(1, n+1):
            for j in range(1, n+1):
                if dist[i][k] != INF and dist[k][j] != INF:
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    # Check connectivity - must be able to reach every vertex from some starting point
    # Since we need to visit all vertices, check if the graph is strongly connected
    def is_reachable(start):
        visited = set()
        stack = [start]
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            for neighbor, _ in graph[node]:
                if neighbor not in visited:
                    stack.append(neighbor)
        return len(visited) == n

    if not any(is_reachable(i) for i in range(1, n+1)):
        print("No")
        return

    # Use DP over subsets to find minimum cost to visit all vertices
    # dp[mask][i] = minimum cost to have visited all vertices in mask and end at vertex i
    ALL_VISITED = (1 << n) - 1
    dp = {}

    # Initialize: start at each vertex
    for i in range(1, n+1):
        dp[(1 << (i-1)), i] = 0

    # Process all states
    queue = [(0, (1 << (i-1)), i) for i in range(1, n+1)]
    heapq.heapify(queue)

    while queue:
        cost, mask, u = heapq.heappop(queue)
        if dp.get((mask, u), INF) < cost:
            continue
        if mask == ALL_VISITED:
            print(cost)
            return

        for v in range(1, n+1):
            if u == v:
                continue
            if dist[u][v] == INF:
                continue
            new_mask = mask | (1 << (v-1))
            new_cost = cost + dist[u][v]
            if (new_mask, v) not in dp or dp[(new_mask, v)] > new_cost:
                dp[(new_mask, v)] = new_cost
                heapq.heappush(queue, (new_cost, new_mask, v))

    print("No")

main()
```

