def getSmallestString(s: str) -> str:
    n = len(s)
    result = list(s)

    i = 0
    while i < n and s[i] == 'a':
        i += 1

    if i == n:
        result[n - 1] = 'z'
        return ''.join(result)

    start = i
    while i < n and s[i] != 'a':
        i += 1
    end = i

    for j in range(start, end):
        result[j] = chr(ord(result[j]) - 1)

    return ''.join(result)
