```python
def sortVowels(s: str) -> str:
    vowels = set('aeiouAEIOU')
    vowel_chars = []

    # Extract vowels and sort them by ASCII value
    for char in s:
        if char in vowels:
            vowel_chars.append(char)
    vowel_chars.sort()

    # Build result string
    result = []
    vowel_index = 0
    for char in s:
        if char in vowels:
            result.append(vowel_chars[vowel_index])
            vowel_index += 1
        else:
            result.append(char)

    return ''.join(result)
