def numberOfBeautifulIntegers(low, high, k):
    count = 0
    for num in range(low, high + 1):
        if num % k != 0:
            continue
        even_count = 0
        odd_count = 0
        for digit_char in str(num):
            digit = int(digit_char)
            if digit % 2 == 0:
                even_count += 1
            else:
                odd_count += 1
        if even_count == odd_count:
            count += 1
