def min_partitions(s):
    n = len(s)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    def is_balanced(sub):
        if not sub:
            return True
        freq = {}
        for c in sub:
            freq[c] = freq.get(c, 0) + 1
        counts = list(freq.values())
        return all(x == counts[0] for x in counts)

    for i in range(1, n + 1):
        for j in range(i):
            if dp[j] != float('inf') and is_balanced(s[j:i]):
                dp[i] = min(dp[i], dp[j] + 1)

    return dp[n]
