```python
def constructProductMatrix(grid):
    n, m = len(grid), len(grid[0])
    total_product = 1
    mod = 12345

    for i in range(n):
        for j in range(m):
            total_product = (total_product * grid[i][j]) % mod

    result = [[0] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] % mod == 0:
                count_nonzero = 0
                temp_product = 1
                for x in range(n):
                    for y in range(m):
                        if (x != i or y != j):
                            if grid[x][y] % mod == 0:
                                count_nonzero += 1
                            if count_nonzero > 1:
                                break
                            temp_product = (temp_product * grid[x][y]) % mod
                result[i][j] = 0 if count_nonzero > 1 else temp_product
            else:
                inv = pow(grid[i][j], -1, mod)
                result[i][j] = (total_product * inv) % mod

    return result
```

