def solve(s: str, k: int) -> int:
    n = len(s)

    def is_palindrome(t):
        return t == t[::-1]

    def min_changes_semi_palindrome(sub):
        length = len(sub)
        if length == 1:
            return float('inf')
        min_changes = float('inf')
        for d in range(1, length):
            if length % d != 0:
                continue
            changes = 0
            for rem in range(d):
                group = []
                idx = rem
                while idx < length:
                    group.append(sub[idx])
                    idx += d
                if not is_palindrome(group):
                    changes += sum(1 for i in range(len(group) // 2) if group[i] != group[-i-1])
            min_changes = min(min_changes, changes)
        return min_changes if min_changes != float('inf') else float('inf')

    # Precompute cost for every substring
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n+1):
            substr = s[i:j]
            cost[i][j-1] = min_changes_semi_palindrome(substr)

    # DP: dp[i][p] = min cost to split s[:i] into p parts
    INF = float('inf')
    dp = [[INF] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for p in range(1, min(k, i) + 1):
            for j in range(p - 1, i):
                if dp[j][p - 1] != INF:
                    dp[i][p] = min(dp[i][p], dp[j][p - 1] + cost[j][i - 1])

    return dp[n][k]
```

