def countSubMultisets(nums, l, r):
    MOD = 10**9 + 7
    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1

    dp = [0] * (r + 1)
    dp[0] = 1

    for num, count in freq.items():
        new_dp = dp[:]
        for remainder in range(num):
            total = 0
            for s in range(remainder, r + 1, num):
                total = (total + dp[s]) % MOD
                if s >= num * (count + 1):
                    total = (total - dp[s - num * (count + 1)]) % MOD
                new_dp[s] = (new_dp[s] + total - dp[s]) % MOD
        dp = new_dp

    result = 0
    for i in range(l, r + 1):
        result = (result + dp[i]) % MOD
    return result
