def waysToReachStair(k):
    if k == 0:
        return 2
    dp = {}

    def dfs(pos, jump, last_down):
        if pos < 0:
            return 0
        if (pos, jump, last_down) in dp:
            return dp[(pos, jump, last_down)]
        if pos == k:
            result = 1
        else:
            result = 0
        # Option 1: Go up
        result += dfs(pos + (1 << jump), jump + 1, False)
        # Option 2: Go down (if allowed)
        if not last_down and pos > 0:
            result += dfs(pos - 1, jump, True)
        dp[(pos, jump, last_down)] = result
        return result

    return dfs(1, 0, False)
