def findKthSmallestAmount(coins, k):
    import heapq
    from math import gcd

    def lcm(a, b):
        return a * b // gcd(a, b)

    def count_multiples(x):
        result = 0
        for i in range(1, 1 << len(coins)):
            current_lcm = 1
            cnt = 0
            for j in range(len(coins)):
                if i & (1 << j):
                    current_lcm = lcm(current_lcm, coins[j])
                    cnt += 1
                    if current_lcm > x:
                        break
            if current_lcm <= x:
                if cnt % 2 == 1:
                    result += x // current_lcm
                else:
                    result -= x // current_lcm
        return result

    left, right = 1, k * min(coins)
    while left < right:
        mid = (left + right) // 2
        if count_multiples(mid) < k:
            left = mid + 1
        else:
            right = mid
    return left
