def minimumDeletions(word: str, k: int) -> int:
    from collections import Counter
    freq = sorted(Counter(word).values())
    min_deletions = float('inf')

    for target in freq:
        deletions = 0
        for f in freq:
            if f < target:
                deletions += f
            elif f > target + k:
                deletions += f - (target + k)
