    def merge(s1: str, s2: str) -> str:
        if s2 in s1:
            return s1
        for i in range(len(s1)):
            if s1[i:] == s2[:len(s1)-i]:
                return s1 + s2[len(s1)-i:]
        return s1 + s2

    candidates = []
    perms = [a, b, c]
    from itertools import permutations
    for p in permutations([a, b, c]):
        res = ""
        for s in p:
            res = merge(res, s)
        candidates.append(res)

    min_len = min(len(cand) for cand in candidates)
    candidates = [cand for cand in candidates if len(cand) == min_len]
    candidates.sort()
    return candidates[0]
