def maximizeXorProduct(a, b, n):
    MOD = 10**9 + 7
    x = 0
    for i in range(n - 1, -1, -1):
        bit = 1 << i
        xor_a = (a ^ x) & bit
        xor_b = (b ^ x) & bit
        if not xor_a and not xor_b:
            x |= bit
        elif xor_a and xor_b:
            continue
        else:
            if (a ^ (x | bit)) * (b ^ (x | bit)) > (a ^ x) * (b ^ x):
                x |= bit
    return ((a ^ x) * (b ^ x)) % MOD
```

