def minOperations(nums, k):
    nums.sort()
    n = len(nums)
    median_idx = (n - 1) // 2 if n % 2 == 1 else n // 2
    median = nums[median_idx]

    operations = 0
    for i in range(n):
        if i < median_idx:
            if nums[i] > k:
                operations += nums[i] - k
        elif i > median_idx:
            if nums[i] < k:
                operations += k - nums[i]
        else:  # i == median_idx
            operations += abs(nums[i] - k)
    return operations
