            elif grid[i][j] == 'G':
                goal = (i, j)
            elif grid[i][j] == 'o':
                candies.append((i, j))

    def bfs_dist(sx, sy):
        dist = [[-1] * W for _ in range(H)]
        q = deque([(sx, sy)])
        dist[sx][sy] = 0
        while q:
            x, y = q.popleft()
            for dx, dy in [(0,1), (1,0), (0,-1), (-1,0)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] != '#' and dist[nx][ny] == -1:
                    dist[nx][ny] = dist[x][y] + 1
                    q.append((nx, ny))
        return dist

    d_start = bfs_dist(start[0], start[1])
    d_goal = bfs_dist(goal[0], goal[1])

    if d_start[goal[0]][goal[1]] == -1 or d_start[goal[0]][goal[1]] > T:
        print(-1)
        return

    candy_dists = []
    for cx, cy in candies:
        dc = bfs_dist(cx, cy)
        candy_dists.append([dc[start[0]][start[1]], dc[goal[0]][goal[1]]] + [dc[ox][oy] for ox, oy in candies])

    n_candies = len(candies)
    if n_candies == 0:
        print(0)
        return

    INF = float('inf')
    dp = [[INF] * (1 << n_candies) for _ in range(n_candies)]
    for i in range(n_candies):
        d_sc = candy_dists[i][0]
        if d_sc != -1:
            dp[i][1 << i] = d_sc

    for mask in range(1 << n_candies):
        for u in range(n_candies):
            if dp[u][mask] == INF or not (mask & (1 << u)):
                continue
            for v in range(n_candies):
                if mask & (1 << v):
                    continue
                new_mask = mask | (1 << v)
                cost = dp[u][mask] + candy_dists[u][v+2]
                if cost < dp[v][new_mask]:
                    dp[v][new_mask] = cost

    ans = 0
    for mask in range(1 << n_candies):
        for u in range(n_candies):
            if dp[u][mask] == INF:
                continue
            total = dp[u][mask] + candy_dists[u][1]
            if total <= T:
                ans = max(ans, bin(mask).count('1'))

    print(ans)

