def punishmentNumber(n: int) -> int:
    def can_partition(s, target):
        if not s:
            return target == 0
        for i in range(1, len(s) + 1):
            left = s[:i]
            num = int(left)
            if num > target:
                break
            if can_partition(s[i:], target - num):
                return True
        return False

    total = 0
    for i in range(1, n + 1):
        square = i * i
        if can_partition(str(square), i):
            total += square
    return total
