def solve(n, queries):
    nums = [0] * n
    result = []
    adjacent_count = 0

    for index, color in queries:
        old_color = nums[index]
        nums[index] = color

        # Check and update adjacent pairs involving the changed index
        # Check left neighbor (index-1, index)
        if index > 0:
            if nums[index-1] != 0 and nums[index-1] == old_color:
                adjacent_count -= 1
            if nums[index-1] != 0 and nums[index-1] == color:
                adjacent_count += 1

        # Check right neighbor (index, index+1)
        if index < n - 1:
            if nums[index+1] != 0 and nums[index+1] == old_color:
                adjacent_count -= 1
            if nums[index+1] != 0 and nums[index+1] == color:
                adjacent_count += 1

        result.append(adjacent_count)

    return result
