import sys

def solve():
    def count_at_distance(n, x, k):
        if k == 0:
            return 1 if x <= n else 0

        def get_path(v):
            path = []
            while v:
                path.append(v)
                v //= 2
            return path

        def get_descendants(root, depth, limit):
            if depth == 0:
                return 1 if root <= limit else 0
            left = root * 2
            right = root * 2 + 1
            if left > limit:
                return 0
            if right > limit:
                return get_descendants(left, depth - 1, limit)
            return get_descendants(left, depth - 1, limit) + get_descendants(right, depth - 1, limit)

        path_x = get_path(x)
        result = 0

        # Count descendants at distance k
        d = k
        cur = x
        while d >= 0 and cur <= n:
            if d == 0:
                result += 1
                break
            cur *= 2
            d -= 1
            if cur <= n:
                result += get_descendants(cur + 1, d - 1, n) if d > 0 else 1

        # Count ancestors and their other subtrees
        ancestors = []
        temp = x
        while temp:
            ancestors.append(temp)
            temp //= 2

        for i in range(1, min(k, len(ancestors)) + 1):
            if i == k:
                if ancestors[i-1] <= n:
                    result += 1
            else:
                parent = ancestors[i-1]
                sibling = parent ^ 1
                remaining = k - i - 1
                if sibling <= n and remaining >= 0:
                    result += get_descendants(sibling, remaining, n)

        return result

    data = sys.stdin.read().split()
    t = int(data[0])
    index = 1
    for _ in range(t):
        n = int(data[index])
        x = int(data[index+1])
        k = int(data[index+2])
        index += 3
        print(count_at_distance(n, x, k))

solve()
