def minimumCost(source: str, target: str, original: list, changed: list, cost: list) -> int:
    import heapq
    from collections import defaultdict

    # Build graph
    graph = defaultdict(list)
    for o, c, z in zip(original, changed, cost):
        graph[o].append((c, z))

    # Precompute shortest path between all pairs of characters
    def dijkstra(start):
        dist = {chr(i): float('inf') for i in range(ord('a'), ord('z') + 1)}
        dist[start] = 0
        heap = [(0, start)]

        while heap:
            d, node = heapq.heappop(heap)
            if d > dist[node]:
                continue
            for neighbor, weight in graph[node]:
                new_dist = d + weight
                if new_dist < dist[neighbor]:
                    dist[neighbor] = new_dist
                    heapq.heappush(heap, (new_dist, neighbor))
        return dist

    # Compute shortest paths for all relevant characters
    min_cost_map = {}
    all_chars = set(original + changed)
    for char in all_chars:
        min_cost_map[char] = dijkstra(char)

    total_cost = 0
    for s_char, t_char in zip(source, target):
        if s_char == t_char:
            continue
        if s_char not in min_cost_map or t_char not in min_cost_map[s_char] or min_cost_map[s_char][t_char] == float('inf'):
            return -1
        total_cost += min_cost_map[s_char][t_char]

    return total_cost
