def countCompleteSubstrings(word: str, k: int) -> int:
    def check(s, k):
        if len(s) % k != 0:
            return False
        unique_count = len(set(s))
        expected_length = unique_count * k
        if len(s) != expected_length:
            return False
        from collections import Counter
        cnt = Counter(s)
        for char in cnt:
            if cnt[char] != k:
                return False
        for i in range(len(s) - 1):
            if abs(ord(s[i]) - ord(s[i + 1])) > 2:
                return False
        return True

    n = len(word)
    ans = 0
    # Split word by invalid adjacent differences
    start = 0
    for end in range(n):
        if end > 0 and abs(ord(word[end]) - ord(word[end - 1])) > 2:
            # Process segment word[start:end]
            segment = word[start:end]
            for seg_start in range(len(segment)):
                for unique_chars in range(1, 27):
                    length = unique_chars * k
                    if seg_start + length > len(segment):
                        break
                    substr = segment[seg_start:seg_start + length]
                    if check(substr, k):
                        ans += 1
            start = end
    # Handle last segment
    segment = word[start:]
    for seg_start in range(len(segment)):
        for unique_chars in range(1, 27):
            length = unique_chars * k
            if seg_start + length > len(segment):
                break
            substr = segment[seg_start:seg_start + length]
            if check(substr, k):
                ans += 1
    return ans
```

