import sys
from collections import defaultdict, deque

def main():
    data = sys.stdin.read().splitlines()
    n = int(data[0])
    prereqs = {}

    for i in range(1, n + 1):
        line = list(map(int, data[i].split()))
        c = line[0]
        if c > 0:
            prereqs[i] = line[1:]
        else:
            prereqs[i] = []

    # We need to read book 1 -> find all prerequisites recursively
    required = set()
    stack = [1]

    while stack:
        book = stack.pop()
        for p in prereqs[book]:
            if p not in required:
                required.add(p)
                stack.append(p)

    # Build reverse dependency graph for topological sort
    indegree = {i: 0 for i in range(1, n + 1)}
    graph = defaultdict(list)

    for book, preds in prereqs.items():
        for p in preds:
            graph[p].append(book)
            if book in required:
                indegree[book] += 1

    # Topological sort using Kahn's algorithm on required nodes
    q = deque()
    for node in required:
        if indegree[node] == 0:
            q.append(node)

    result = []
    while q:
        curr = q.popleft()
        result.append(curr)
        for neighbor in graph[curr]:
            if neighbor in required:
                indegree[neighbor] -= 1
                if indegree[neighbor] == 0:
                    q.append(neighbor)

    print(" ".join(map(str, result)))

main()
