def shortestBeautifulSubstring(s: str, k: int) -> str:
    n = len(s)
    min_length = float('inf')
    candidates = []

    # Find all substrings with exactly k ones
    for i in range(n):
        one_count = 0
        for j in range(i, n):
            if s[j] == '1':
                one_count += 1
            if one_count == k:
                length = j - i + 1
                if length < min_length:
                    min_length = length
                    candidates = [s[i:j+1]]
                elif length == min_length:
                    candidates.append(s[i:j+1])
                break

    # If no valid substring found
    if not candidates:
        return ""

    # Return lexicographically smallest
    return min(candidates)
