def numberOfPowerfulInt(start: int, finish: int, limit: int, s: str) -> int:
    def count_up_to(n):
        sn = str(n)
        len_s = len(s)
        len_n = len(sn)
        if len_s > len_n:
            return 0
        if len_s == len_n:
            if s > sn:
                return 0
            else:
                return 1 if all(c <= str(limit) for c in s) else 0
        # Count numbers with suffix s and digits <= limit, having less than len_n digits
        res = 0
        # Numbers with digits < len_n but >= len_s
        for d in range(len_s, len_n):
            # First digit: from 1 to min(limit, 9) but we consider positions
            # We fix last len_s digits as s, so first d - len_s digits to choose
            if d == len_s:
                if s[0] != '0' and all(c <= str(limit) for c in s):
                    res += 1
            else:
                # d > len_s: we have d - len_s free digits at front
                # first digit: 1 to limit (cannot be 0), others: 0 to limit
                res += (limit) * (limit + 1) ** (d - len_s - 1)
        # Now count numbers with exactly len_n digits and <= n
        prefix_max = sn[:-len_s]
        suffix_str = sn[-len_s:]
        # Try all prefixes from 0 to prefix_max, but must satisfy digit <= limit
        # But note: entire number must be <= n when suffix is s
        if s > suffix_str:
            upper_prefix = str(int(prefix_max) - 1) if prefix_max != "" else "-1"
        else:
            upper_prefix = prefix_max
        if upper_prefix == "-1":
            pass  # no valid prefix
        else:
            # Count numbers with prefix in [1, int(upper_prefix)] and digits <= limit
            res += count_limited_numbers_less_equal(upper_prefix, limit)
        return res

    def count_limited_numbers_less_equal(num_str, lim):
        if not num_str or num_str == "0":
            return 0
        n = len(num_str)
        dp = [0] * (n + 1)
        dp[0] = 1
        tight = True
        for i in range(n):
            digit = int(num_str[i])
            up = min(digit, lim) if tight else lim
            new_tight = tight and (up == digit)
            cnt = 0
            for d in range(0, up + 1):
                if i == 0 and d == 0:
                    continue
                cnt += dp[i]
            dp[i+1] = cnt
            tight = new_tight
        return sum(dp[1:])

    return count_up_to(finish) - count_up_to(start - 1)
