def canSplitArray(nums, m):
    n = len(nums)
    if n <= 2:
        return True

    prefix_sum = [0]
    for num in nums:
        prefix_sum.append(prefix_sum[-1] + num)

    def canSplit(left, right):
        if left >= right:
            return True
        total = prefix_sum[right + 1] - prefix_sum[left]
        if right - left + 1 == 2:
            return True
        for mid in range(left, right):
            left_len = mid - left + 1
            right_len = right - mid
            left_sum = prefix_sum[mid + 1] - prefix_sum[left]
            right_sum = prefix_sum[right + 1] - prefix_sum[mid + 1]
            left_ok = (left_len == 1) or (left_sum >= m)
            right_ok = (right_len == 1) or (right_sum >= m)
            if left_ok and right_ok:
                if canSplit(left, mid) and canSplit(mid + 1, right):
                    return True
        return False

    return canSplit(0, n - 1)
