def canTraverseAllPairs(nums):
    if len(nums) == 1:
        return True

    if 1 in nums:
        return False

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[rx] = ry

    def prime_factors(n):
        factors = set()
        d = 2
        while d * d <= n:
            while n % d == 0:
                factors.add(d)
                n //= d
            d += 1
        if n > 1:
            factors.add(n)
        return factors

    parent = list(range(len(nums)))
    factor_map = {}

    for i, num in enumerate(nums):
        factors = prime_factors(num)
        for f in factors:
            if f in factor_map:
                union(i, factor_map[f])
            else:
                factor_map[f] = i

    root = find(0)
    return all(find(i) == root for i in range(len(nums)))
