def specialPerm(nums):
    MOD = 10**9 + 7
    n = len(nums)
    compatible = [[False] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if i != j and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                compatible[i][j] = True

    dp = {}

    def solve(mask, last):
        if mask == (1 << n) - 1:
            return 1
        if (mask, last) in dp:
            return dp[(mask, last)]

        result = 0
        for i in range(n):
            if not (mask & (1 << i)) and (last == -1 or compatible[last][i]):
                result = (result + solve(mask | (1 << i), i)) % MOD

        dp[(mask, last)] = result
        return result

    return solve(0, -1)
```

