def maxPartitionsAfterOperations(s: str, k: int) -> int:
    n = len(s)

    def count_partitions(string):
        i = 0
        partitions = 0
        while i < len(string):
            seen = set()
            j = i
            while j < len(string) and len(seen) <= k:
                if string[j] in seen or len(seen) < k:
                    seen.add(string[j])
                    j += 1
                else:
                    break
            partitions += 1
            i = j
        return partitions

    best = 0
    # Try changing each position to every possible letter
    for i in range(n):
        for c in 'abcdefghijklmnopqrstuvwxyz':
            if s[i] == c:
                continue
            new_s = s[:i] + c + s[i+1:]
            best = max(best, count_partitions(new_s))

