def maximumJumps(nums, target):
    n = len(nums)
    dp = [-1] * n
    dp[0] = 0

    for i in range(n):
        if dp[i] == -1:
            continue
        for j in range(i + 1, n):
            diff = nums[j] - nums[i]
            if -target <= diff <= target:
                if dp[j] < dp[i] + 1:
                    dp[j] = dp[i] + 1

    return dp[n - 1]
```

```python
def longestSubsequence(nums, target):
    n = len(nums)
    dp = [[-1] * (target + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = 0

    for i in range(1, n + 1):
        num = nums[i - 1]
        for t in range(target + 1):
            dp[i][t] = dp[i - 1][t]
            if t >= num and dp[i - 1][t - num] != -1:
                if dp[i][t] == -1:
                    dp[i][t] = dp[i - 1][t - num] + 1
                else:
                    dp[i][t] = max(dp[i][t], dp[i - 1][t - num] + 1)

    return dp[n][target] if dp[n][target] != -1 else -1
```

