def maximumSubarraySum(nums, k):
    n = len(nums)
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + nums[i]

    val_to_min_prefix = {}
    max_sum = float('-inf')

    for i in range(n):
        curr = nums[i]

        # Check for target values that form absolute difference k
        for target in [curr - k, curr + k]:
            if target in val_to_min_prefix:
                j = val_to_min_prefix[target]
                current_sum = prefix_sum[i + 1] - prefix_sum[j]
                max_sum = max(max_sum, current_sum)

        # Maintain the earliest occurrence of curr with minimum prefix sum
        if curr not in val_to_min_prefix:
            val_to_min_prefix[curr] = i
        else:
            if prefix_sum[i] < prefix_sum[val_to_min_prefix[curr]]:
                val_to_min_prefix[curr] = i

    return max_sum if max_sum != float('-inf') else 0
```

