def solve():
    n, m = map(int, input().split())
    edges = []
    for _ in range(m):
        u, v = map(int, input().split())
        edges.append((u, v))

    k = int(input())
    forbidden = []
    for _ in range(k):
        x, y = map(int, input().split())
        forbidden.append((x, y))

    q = int(input())
    queries = []
    for _ in range(q):
        p, q = map(int, input().split())
        queries.append((p, q))

    def is_good(graph):
        def bfs(start, end, graph):
            visited = set()
            queue = [start]
            visited.add(start)

            while queue:
                curr = queue.pop(0)
                if curr == end:
                    return True

                for neighbor in graph.get(curr, []):
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)
            return False

        for x, y in forbidden:
            if bfs(x, y, graph):
                return False
        return True

    for p, q in queries:
        new_edges = edges + [(p, q)]
        graph = {}
        for u, v in new_edges:
            if u not in graph:
                graph[u] = []
            if v not in graph:
                graph[v] = []
            graph[u].append(v)
            graph[v].append(u)

        if is_good(graph):
            print("Yes")
        else:
            print("No")

solve()
