def numberOfWays(n, x):
    dp = [1] + [0] * n
    for i in range(1, n + 1):
        power = i ** x
        if power > n: break
        for j in range(n, power - 1, -1):
            dp[j] = (dp[j] + dp[j - power]) % (10**9 + 7)
    return dp[n]
