def count_sub_multisets(nums, l, r):
    MOD = 10**9 + 7
    count_zero = nums.count(0)
    nums = [num for num in nums if num != 0]
    max_sum = sum(nums)
    if max_sum == 0 and l == 0:
        return (count_zero > 0)
    if max_sum == 0 and l > 0:
        return 0
    dp = [0] * (max_sum + 1)
    dp[0] = 1
    for num in nums:
        for i in range(num, max_sum + 1):
            dp[i] = (dp[i] + dp[i - num]) % MOD
    ans = 0
    for i in range(l, r + 1):
        ans = (ans + dp[i]) % MOD
    ans = (ans * pow(2, count_zero, MOD)) % MOD
    return ans
