    def can_place(grid, tile_idx, tiles_used):
        # Find first uncovered cell
        uncovered = None
        for i in range(H):
            for j in range(W):
                if grid[i][j] == -1:
                    uncovered = (i, j)
                    break
            if uncovered:
                break

        # All cells covered
        if uncovered is None:
            return True

        r, c = uncovered

        # Try each unused tile
        for idx in range(N):
            if idx in tiles_used:
                continue

            a, b = tiles[idx]

            # Try both orientations
            for h, w in [(a, b), (b, a)]:
                # Try to place at (r, c)
                if r + h <= H and c + w <= W:
                    # Check if all cells in rectangle are uncovered
                    valid = True
                    for i in range(r, r + h):
                        for j in range(c, c + w):
                            if grid[i][j] != -1:
                                valid = False
                                break
                        if not valid:
                            break

                    if valid:
                        # Place tile
                        for i in range(r, r + h):
                            for j in range(c, c + w):
                                grid[i][j] = idx

                        tiles_used.add(idx)

                        if can_place(grid, tile_idx + 1, tiles_used):
                            return True

                        # Remove tile
                        tiles_used.remove(idx)
                        for i in range(r, r + h):
                            for j in range(c, c + w):
                                grid[i][j] = -1

        return False

    grid = [[-1] * W for _ in range(H)]
    if can_place(grid, 0, set()):
