def canTraverseAllPairs(nums):
    from math import gcd
    from collections import defaultdict

    if len(nums) == 1:
        return True

    # Check if all numbers share a common factor > 1
    if any(num == 1 for num in nums):
        return False

    # Union-Find data structure
    parent = list(range(len(nums)))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # Map each prime factor to indices that contain it
    prime_to_indices = defaultdict(list)

    def get_prime_factors(n):
        factors = set()
        d = 2
        while d * d <= n:
            while n % d == 0:
                factors.add(d)
                n //= d
            d += 1
        if n > 1:
            factors.add(n)
        return factors

    # Get prime factors for each number
    for i, num in enumerate(nums):
        primes = get_prime_factors(num)
        for prime in primes:
            prime_to_indices[prime].append(i)

    # Union indices that share a prime factor
    for indices in prime_to_indices.values():
        for i in range(1, len(indices)):
            union(indices[0], indices[i])

    # Check if all indices are in the same connected component
    root = find(0)
    return all(find(i) == root for i in range(len(nums)))
