def getSmallestString(s: str, k: int) -> str:
    def char_distance(c1, c2):
        # Minimum distance between two characters in cyclic order
        diff = abs(ord(c1) - ord(c2))
        return min(diff, 26 - diff)

    result = list(s)
    remaining = k

    for i in range(len(result)):
        if remaining == 0:
            break

        # Try to change current character to 'a', 'b', 'c', ... until we can't
        current_char = result[i]

        # Try each character from 'a' onwards
        for target_char in 'abcdefghijklmnopqrstuvwxyz':
            dist = char_distance(current_char, target_char)

            # If we can afford this change and target is smaller, or same and lexicographically better
            if dist <= remaining:
                remaining -= dist
                result[i] = target_char
                break

            # If target_char >= current_char, no point trying further
            if target_char > current_char:
                break

    return ''.join(result)
