def minGroupsForValidAssignment(nums):
    from collections import Counter
    freq = Counter(nums)
    min_freq = min(freq.values())
    for k in range(min_freq, 0, -1):
        groups = 0
        for f in freq.values():
            q, r = divmod(f, k + 1)
            if r == 0:
                groups += q
            elif r <= k:
                groups += q + 1
            else:
                groups = float('inf')
                break
        if groups != float('inf'):
            return groups
    return len(nums)
